// Minimal local MP4 muxer for H.264 WebCodecs output.
const u16=n=>[(n>>>8)&255,n&255],u32=n=>[(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];
const str=s=>[...new TextEncoder().encode(s)];
const box=(t,p=[])=>new Uint8Array([...u32(8+p.length),...str(t),...p]);
const concat=(...xs)=>{let n=0;for(const x of xs)n+=x.length;const o=new Uint8Array(n);let p=0;for(const x of xs){o.set(x,p);p+=x.length;}return o;};
const full=(t,v,f,p=[])=>box(t,[v,...u32(f).slice(1),...p]);
const fixed16=v=>u32(Math.round(v*65536));
const fixed8=v=>u16(Math.round(v*256));
const matrix=()=>[...fixed16(1),...fixed16(1),0,0,0,0,0,0,...fixed16(1),0,0,0,0];
const language=()=>u16(0x15a5);
export class ArrayBufferTarget{constructor(){this.buffer=null;}}
export class FileSystemWritableFileStreamTarget{constructor(stream){this.stream=stream;}}
export class StreamTarget{constructor(stream){this.stream=stream;}}
export class Muxer{
 constructor({target,video}={}){this.target=target;this.video=video;this.samples=[];this.decoderConfig=null;this.closed=false;}
 addVideoChunk(chunk,meta={}){if(this.closed)throw new Error('Muxer is finalized.');const data=new Uint8Array(chunk.byteLength);chunk.copyTo(data);if(!this.decoderConfig&&meta.decoderConfig)this.decoderConfig=meta.decoderConfig;this.samples.push({data,key:chunk.type==='key'});}
 finalize(){if(this.closed)return;this.closed=true;if(!this.samples.length)throw new Error('No video samples were encoded.');const fps=this.video.frameRate||30,w=this.video.width,h=this.video.height,ts=90000,dur=Math.max(1,Math.round(ts/fps)),total=dur*this.samples.length;const ftyp=box('ftyp',[...str('isom'),...u32(0x200),...str('isomiso2avc1mp41')]);const mdatData=concat(...this.samples.map(s=>s.data));const mdat=box('mdat',[...mdatData]);let moov=makeMoov(w,h,fps,ts,total,this.samples,this.decoderConfig,[]);const first=ftyp.length+moov.length+8;let offsets=[],p=first;for(const s of this.samples){offsets.push(p);p+=s.data.length;}moov=makeMoov(w,h,fps,ts,total,this.samples,this.decoderConfig,offsets);this.target.buffer=concat(ftyp,moov,mdat).buffer;}
}
function makeMoov(w,h,fps,ts,total,samples,config,offsets){const mvhd=full('mvhd',0,0,[...u32(0),...u32(0),...u32(1000),...u32(Math.round(total*1000/ts)),...fixed16(1),...fixed8(1),0,0,0,0,...matrix(),...new Array(6).fill(0).flatMap(()=>u32(0)),...u32(2)]);const tkhd=full('tkhd',0,7,[...u32(0),...u32(0),...u32(1),...u32(0),...u32(total),...u32(0),...u32(0),...u16(0),...u16(0),...fixed8(0),...fixed8(0),...matrix(),...fixed16(w),...fixed16(h)]);const mdhd=full('mdhd',0,0,[...u32(0),...u32(0),...u32(ts),...u32(total),...language(),...u16(0)]);const hdlr=full('hdlr',0,0,[...u32(0),...str('vide'),...new Array(12).fill(0),...str('VideoHandler\0')]);const vmhd=full('vmhd',0,1,[...u16(0),...u16(0),...u16(0),...u16(0)]);const dref=full('dref',0,0,[...u32(1),...full('url ',0,1)]);const dinf=box('dinf',[...dref]);const avcC=box('avcC',Array.from(config?.description||new Uint8Array()));const avc1=box('avc1',[...new Array(6).fill(0),...u16(1),...new Array(16).fill(0),...u16(w),...u16(h),...fixed16(72),...fixed16(72),...u32(0),...u16(1),...new Array(32).fill(0),...u16(0x18),...u16(0xffff),...avcC]);const stsd=full('stsd',0,0,[...u32(1),...avc1]);const dur=Math.max(1,Math.round(ts/fps));const stts=full('stts',0,0,[...u32(1),...u32(samples.length),...u32(dur)]);const stsc=full('stsc',0,0,[...u32(1),...u32(1),...u32(1),...u32(1)]);const stsz=full('stsz',0,0,[...u32(0),...u32(samples.length),...samples.flatMap(s=>u32(s.data.length))]);const stco=full('stco',0,0,[...u32(offsets.length),...offsets.flatMap(o=>u32(o))]);const keys=samples.map((s,i)=>s.key?i+1:null).filter(Boolean);const stss=keys.length===samples.length?null:full('stss',0,0,[...u32(keys.length),...keys.flatMap(u32)]);const stbl=box('stbl',[...stsd,...stts,...stsc,...stsz,...stco,...(stss?[...stss]:[])]);const minf=box('minf',[...vmhd,...dinf,...stbl]);const mdia=box('mdia',[...mdhd,...hdlr,...minf]);const trak=box('trak',[...tkhd,...mdia]);return box('moov',[...mvhd,...trak]);}
